def Ω : Set (ℝ × ℝ) := Set.Icc (0 : ℝ) 1 ×ˢ Set.Icc (0 : ℝ) 1
def left : Set (ℝ × ℝ) :=
  {p | p.1 = 0 ∧ p.2 ∈ Set.Icc (0 : ℝ) 1}
def right : Set (ℝ × ℝ) :=
  {p | p.1 = 1 ∧ p.2 ∈ Set.Icc (0 : ℝ) 1}
def bottom : Set (ℝ × ℝ) :=
  {p | p.2 = 0 ∧ p.1 ∈ Set.Ioo (0 : ℝ) 1}
def top : Set (ℝ × ℝ) :=
  {p | p.2 = 1 ∧ p.1 ∈ Set.Ioo (0 : ℝ) 1}

noncomputable def circleAvg (u : ℝ × ℝ → ℝ) (p : ℝ × ℝ) (r : ℝ) :=
  (1 / (2 * Real.pi)) *
    ∫ θ in (0)..(2 * Real.pi),
      u (p.1 + r * Real.cos θ, p.2 + r * Real.sin θ)

def HarmonicOn (u : ℝ × ℝ → ℝ) (D : Set (ℝ × ℝ)) : Prop :=
  ∀ p ∈ D, ∀ r > 0,
    Metric.ball p r ⊆ D →
      u p = circleAvg u p r

theorem brown_7a :
  ∃ u : (ℝ × ℝ) → ℝ,
    ContinuousOn u (closure Ω) ∧
    HarmonicOn u (interior Ω) ∧
    (∀ p ∈ left   ∩ Ω, u p = 0) ∧
    (∀ p ∈ right  ∩ Ω, u p = 0) ∧
    (∀ p ∈ bottom ∩ Ω, u p = 0) ∧
    (∀ p ∈ top    ∩ Ω, u p = 100) ∧
    u (1/2, 1/2) = 25 := by
  sorry

theorem question_4 :
  let P : Set (ℝ × ℝ × ℝ) :=
    { p | p.1 - 2 * p.2.1 + 3 * p.2.2 = 0 }
  let XY : Set (ℝ × ℝ × ℝ) :=
    { p | p.2.2 = 0 }
  let v₁ : ℝ × ℝ × ℝ := (2, (1, 0))
  let v₂ : ℝ × ℝ × ℝ := (-3, (0, 1))
  ((v₁ ∈ P ∧ v₁ ∈ XY) ∧
   (v₂ ∈ P ∧ v₂ ∈ XY) ∧
   LinearIndependent ℝ ![v₁, v₂] ∧
   (↑(Submodule.span ℝ ({v₁, v₂} : Set (ℝ × ℝ × ℝ))) =
      { p : ℝ × ℝ × ℝ | p ∈ P ∧ p ∈ XY })) := by
  sorry

problem:
The set of nice terms is defined as follows: \begin{itemize}
    \item Any letter a, b, c, or d is a nice term;
    \item If $s_1, s_2$ are nice terms, so is $[s_1\circ s_2]$; and
    \item Nothing else is a nice term.
\end{itemize}
    A proper initial segment of a nice term $t$ is a non-empty substring (consecutive chunk) of $t$ with fewer letters and starting from the first letter of $t$; that is, $s$ is a proper initial segment of $t$ if $s\neq \varepsilon$ and $s$ agrees with $t$ symbol by symbol, read from the left, but $t$ is longer. Prove that any proper initial segment of a nice term has more character `\texttt{$[$}'s than `\texttt{$]$}'s.

